-- Metadata and hashes only; no Auth tokens, object bytes, or user rows.
WITH catalog_search_path AS MATERIALIZED (
 SELECT set_config('search_path','pg_catalog',true)
)
SELECT jsonb_build_object(
 'server_version',current_setting('server_version'),
 'extensions_schema',(SELECT jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',ARRAY(SELECT a::text FROM unnest(coalesce(nspacl,acldefault('n',nspowner))) a ORDER BY a::text)) FROM pg_namespace WHERE nspname='extensions'),
 'extensions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'schema_owner',pg_get_userbyid(n.nspowner)) ORDER BY e.extname),'[]'::jsonb) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'default_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'global'),'kind',d.defaclobjtype::text,'acl',ARRAY(SELECT a::text FROM unnest(d.defaclacl) a ORDER BY a::text)) ORDER BY pg_get_userbyid(d.defaclrole),coalesce(n.nspname,'global'),d.defaclobjtype::text),'[]'::jsonb) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),
 'event_triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled::text,'tags',e.evttags,'owner',pg_get_userbyid(e.evtowner),'function_schema',n.nspname,'function_name',p.proname,'function_owner',pg_get_userbyid(p.proowner),'function_acl',ARRAY(SELECT a::text FROM unnest(coalesce(p.proacl,acldefault('f',p.proowner))) a ORDER BY a::text),'definition',replace(pg_get_functiondef(p.oid),E'\r\n',E'\n')) ORDER BY e.evtname),'[]'::jsonb) FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid JOIN pg_namespace n ON n.oid=p.pronamespace),
 'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',ARRAY(SELECT a::text FROM unnest(coalesce(c.relacl,acldefault('r',c.relowner))) a ORDER BY a::text)) ORDER BY n.nspname,c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','auth','storage','realtime') AND c.relkind IN ('r','p')),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'mode',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY schemaname,tablename,policyname),'[]'::jsonb) FROM pg_policies WHERE schemaname IN ('public','auth','storage','realtime')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled::text,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY n.nspname,c.relname,t.tgname),'[]'::jsonb) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname IN ('public','auth','storage','realtime')),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',ARRAY(SELECT a::text FROM unnest(coalesce(p.proacl,acldefault('f',p.proowner))) a ORDER BY a::text),'definition_hash',md5(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'))) ORDER BY n.nspname,p.oid::regprocedure::text),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','auth','storage','realtime') AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'data',(SELECT jsonb_build_object('auth_users', (SELECT count(*) FROM auth.users),'auth_hash',(SELECT md5(coalesce(string_agg(to_jsonb(u)::text,E'\n' ORDER BY to_jsonb(u)::text),'')) FROM auth.users u),'migrations',(SELECT count(*) FROM supabase_migrations.schema_migrations),'migration_hash',(SELECT md5(coalesce(string_agg(to_jsonb(m)::text,E'\n' ORDER BY to_jsonb(m)::text),'')) FROM supabase_migrations.schema_migrations m),'storage_buckets',(SELECT count(*) FROM storage.buckets),'storage_objects',(SELECT count(*) FROM storage.objects),'storage_hash',(SELECT md5(coalesce(string_agg(to_jsonb(o)::text,E'\n' ORDER BY to_jsonb(o)::text),'')) FROM storage.objects o),'manifest_rows',(SELECT count(*) FROM public.phase8_drive_manifests),'manifest_hash',(SELECT md5(coalesce(string_agg(to_jsonb(m)::text,E'\n' ORDER BY to_jsonb(m)::text),'')) FROM public.phase8_drive_manifests m)))
) AS catalog
FROM catalog_search_path;
